PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS audit_events;DROP TABLE IF EXISTS api_tokens;DROP TABLE IF EXISTS health_check_results;DROP TABLE IF EXISTS health_check_targets;DROP TABLE IF EXISTS alert_events;DROP TABLE IF EXISTS alerts;DROP TABLE IF EXISTS configuration_versions;DROP TABLE IF EXISTS restore_jobs;DROP TABLE IF EXISTS backups;DROP TABLE IF EXISTS job_runs;DROP TABLE IF EXISTS scheduled_jobs;DROP TABLE IF EXISTS service_actions;DROP TABLE IF EXISTS services;DROP TABLE IF EXISTS log_entries;DROP TABLE IF EXISTS log_sources;DROP TABLE IF EXISTS metric_samples;DROP TABLE IF EXISTS reset_tokens;DROP TABLE IF EXISTS sessions;DROP TABLE IF EXISTS servers;DROP TABLE IF EXISTS users;
PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('operator','admin')),status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE reset_tokens(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE servers(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,hostname TEXT UNIQUE NOT NULL,environment TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE metric_samples(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),sampled_at TEXT NOT NULL,cpu REAL NOT NULL,memory REAL NOT NULL,disk REAL NOT NULL,load_average REAL NOT NULL);
CREATE TABLE log_sources(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),name TEXT NOT NULL,kind TEXT NOT NULL,UNIQUE(server_id,name));
CREATE TABLE log_entries(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES log_sources(id),level TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE services(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),name TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(server_id,name));
CREATE TABLE service_actions(id INTEGER PRIMARY KEY,service_id INTEGER NOT NULL REFERENCES services(id),actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,status TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE scheduled_jobs(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),name TEXT NOT NULL,command TEXT NOT NULL,schedule TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(server_id,name));
CREATE TABLE job_runs(id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL REFERENCES scheduled_jobs(id),status TEXT NOT NULL,output TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE backups(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),kind TEXT NOT NULL,status TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE restore_jobs(id INTEGER PRIMARY KEY,backup_id INTEGER NOT NULL REFERENCES backups(id),status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE configuration_versions(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),settings TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(server_id,version));
CREATE TABLE alerts(id INTEGER PRIMARY KEY,server_id INTEGER NOT NULL REFERENCES servers(id),severity TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,resolution_note TEXT NOT NULL,created_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE alert_events(id INTEGER PRIMARY KEY,alert_id INTEGER NOT NULL REFERENCES alerts(id),actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE health_check_targets(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,type TEXT NOT NULL,endpoint TEXT UNIQUE NOT NULL,interval_seconds INTEGER NOT NULL,enabled INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE health_check_results(id INTEGER PRIMARY KEY,target_id INTEGER NOT NULL REFERENCES health_check_targets(id) ON DELETE CASCADE,status TEXT NOT NULL,latency_ms INTEGER NOT NULL,checked_at TEXT NOT NULL);
CREATE TABLE api_tokens(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,scopes TEXT NOT NULL,token_hash TEXT NOT NULL,token_prefix TEXT NOT NULL,status TEXT NOT NULL,rotated_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),server_id INTEGER REFERENCES servers(id),action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
